// Data for /flags: generated by the flag-circle pipeline (export_web.py), do not edit by hand.
import data from './flags.json';

export { imageUrl, placeOnRing } from './ring.js';

/** All flags in circle order; `index` is the place in the circle, 0 at 12 o'clock. */
export const flags = data.flags.map((flag, index) => ({ ...flag, index }));
export const byCode = Object.fromEntries(flags.map((flag) => [flag.code, flag]));
export const stats = data.stats;
export const meta = data.meta;

const fold = (text) =>
	text
		.normalize('NFD')
		.replace(/\p{Diacritic}/gu, '')
		.toLowerCase();

/** Flags whose name contains the query (case and accents ignored), earliest match first. */
export function searchFlags(query, limit = 6) {
	const q = fold(query.trim());
	if (!q) return [];
	return flags
		.map((flag) => ({ flag, at: fold(flag.name).indexOf(q) }))
		.filter(({ at }) => at >= 0)
		.sort((a, b) => a.at - b.at || a.flag.name.localeCompare(b.flag.name))
		.slice(0, limit)
		.map(({ flag }) => flag);
}
